# remove values in runtime output like zod safeParse · arktypeio arktype · Discussion #1336
created: 2025-03-03, last updated: 2026-04-17, [Read more](https://github.com/arktypeio/arktype/discussions/1336)

Hi @isimmons, it looks like what you're after is `onUndeclaredKey`:
```
const userSchema = type({
name: "string",
email: "email"
}).onUndeclaredKey("delete");
...
```
...
There's also a shorthand where instead of `.onUndeclaredKey("delete")` you can do `"+": "delete"` within the schema itself, i.e.
```
const userSchema = type({
name: "string",
email": "email",
"+": "delete"
});
```
...
});
```
And this can be configured per-type as shown above, or if you want this to apply to *all* created types by default, you can configure `onUndeclaredKey` globally, as per https://arktype.io/docs/configuration#onundeclaredkey:
```
import { configure } from "arktype/config";
configure({ onUndeclaredKey: "delete" });
// NB: The core arktype import must be AFTER the config has been set
import { type } from "arktype"'
const userSchema = type({
name: "string",
email: "email"
});
```

# 超直感的なバリデーション?ArkType入門 - Zenn
created: 2025-04-04, last updated: 2026-05-12, [Read more](https://zenn.dev/forcia_tech/articles/202504_hatano_arktype)

## 余分なプロパティに対する挙動
例えばzodの場合、あるオブジェクトのバリデーション定義に対して余分なプロパティがある場合はその値を削除します。
一方、ArkTypeでは余分なプロパティに対しては何もせず検証を通過させます。
...
```
ArkTypeでこの挙動を変更したい場合には、オブジェクトのバリデーション定義に`+`プロパティを追加します。
```
const arkTypeDefinition = type({
name: "string",
// reject: 余計なプロパティがある場合はエラーとする
// delete: 余計なプロパティを削除する
// ignore: 余計なプロパティを無視する(デフォルト)
"+": "reject"
});
```

input.content:
import { type } from "arktype";

const ignoreSchema = type({
  id: "string.uuid",
  name: "string",
  email: "string.email",
  "+": "ignore"
});

const rejectSchema = type({
  id: "string.uuid",
  name: "string",
  email: "string.email",
  "+": "reject"
});

const deleteSchema = type({
  id: "string.uuid",
  name: "string",
  email: "string.email",
  "+": "delete"
});

const validPayload = {
  id: "123e4567-e89b-12d3-a456-426614174000",
  name: "Alice",
  email: "alice@example.com",
  extra: "should be ignored/rejected/deleted"
};

console.log("--- IGNORE SCHEMA ---");
const ignoreResult = ignoreSchema(validPayload);
if (ignoreResult instanceof type.errors) {
  console.log("Error:", ignoreResult.summary);
} else {
  console.log("Success:", JSON.stringify(ignoreResult));
}

console.log("--- REJECT SCHEMA ---");
const rejectResult = rejectSchema(validPayload);
if (rejectResult instanceof type.errors) {
  console.log("Error:", rejectResult.summary);
  console.log("Full error details:", JSON.stringify(rejectResult));
} else {
  console.log("Success:", JSON.stringify(rejectResult));
}

console.log("--- DELETE SCHEMA ---");
const deleteResult = deleteSchema(validPayload);
if (deleteResult instanceof type.errors) {
  console.log("Error:", deleteResult.summary);
} else {
  console.log("Success:", JSON.stringify(deleteResult));
}

import { type } from "arktype";

const rejectSchema = type({
  id: "string.uuid",
  name: "string",
  email: "string.email",
  "+": "reject"
});

const badPayloads = [
  {
    id: "not-a-uuid",
    name: "Alice",
    email: "not-an-email",
    extra: "should be ignored/rejected/deleted"
  },
  {
    id: "123e4567-e89b-12d3-a456-426614174000",
    name: "Alice",
    email: "alice@example.com",
    foo: 1,
    bar: 2
  }
];

for (const payload of badPayloads) {
  console.log("Payload:", JSON.stringify(payload));
  const res = rejectSchema(payload);
  if (res instanceof type.errors) {
    console.log("Summary:", res.summary);
    console.log("Errors array:", JSON.stringify(res));
  } else {
    console.log("Success:", JSON.stringify(res));
  }
}

import * as fs from "node:fs";
import { type } from "arktype";

// Define schemas as required
const ignoreSchema = type({
  id: "string.uuid",
  name: "string",
  email: "string.email",
  "+": "ignore"
});

const rejectSchema = type({
  id: "string.uuid",
  name: "string",
  email: "string.email",
  "+": "reject"
});

const deleteSchema = type({
  id: "string.uuid",
  name: "string",
  email: "string.email",
  "+": "delete"
});

function main() {
  let inputStr = "";
  try {
    inputStr = fs.readFileSync(0, "utf-8").trim();
  } catch (err) {
    console.log("INVALID: Failed to read from stdin");
    process.exit(0);
  }

  if (!inputStr) {
    console.log("INVALID: Empty input");
    process.exit(0);
  }

  let inputJson: any;
  try {
    inputJson = JSON.parse(inputStr);
  } catch (err) {
    console.log("INVALID: Invalid JSON format");
    process.exit(0);
  }

  if (typeof inputJson !== "object" || inputJson === null) {
    console.log("INVALID: Input must be a JSON object");
    process.exit(0);
  }

  const { mode, payload } = inputJson;

  if (mode !== "ignore" && mode !== "reject" && mode !== "delete") {
    console.log(`INVALID: Unknown mode "${mode}"`);
    process.exit(0);
  }

  // Check if payload is present in the input JSON
  if (!("payload" in inputJson)) {
    console.log("INVALID: Missing payload");
    process.exit(0);
  }

  let schema: any;
  if (mode === "ignore") {
    schema = ignoreSchema;
  } else if (mode === "reject") {
    schema = rejectSchema;
  } else {
    schema = deleteSchema;
  }

  const result = schema(payload);

  if (result instanceof type.errors) {
    const errorMessage = result.summary.replace(/\r?\n/g, "; ");
    console.log(`INVALID: ${errorMessage}`);
  } else {
    console.log("VALID");
    console.log(JSON.stringify(result));
  }
}

main();
